"""Render the named-graph property scale series from summary.json (requires matplotlib)."""

import json
from pathlib import Path

import matplotlib

matplotlib.use("Agg")
import matplotlib.pyplot as plt
from matplotlib.ticker import ScalarFormatter


directory = Path(__file__).resolve().parent
records = {case["case"]: case for case in json.loads((directory / "summary.json").read_text())["cases"]}
selected = [records[f"property-named-{roots}"] for roots in (1, 64, 256)]
colors = {"before": "#A23C50", "after": "#087F8C"}
plt.rcParams.update({"font.family": "DejaVu Sans", "font.size": 11,
                     "axes.spines.top": False, "axes.spines.right": False,
                     "axes.labelcolor": "#243247", "text.color": "#243247",
                     "xtick.color": "#243247", "ytick.color": "#243247"})
figure, axes = plt.subplots(1, 2, figsize=(11.8, 5.5))
figure.suptitle("Property-query scaling with a fixed 512-path answer", fontsize=17, weight="bold", y=0.97)
figure.text(0.5, 0.91, "GQL on LMDB · named graph · fanout 32 · result caching disabled",
            ha="center", fontsize=11)

for variant, offset, marker in (("before", -0.055, "o"), ("after", 0.055, "s")):
    values = [case[variant]["latency_us"]["score"] / 1000 for case in selected]
    errors = [case[variant]["latency_us"]["scoreError"] / 1000 for case in selected]
    axes[0].errorbar([x + offset for x in range(3)], values, yerr=errors,
                     marker=marker, markersize=6, capsize=5, linewidth=2,
                     color=colors[variant], label=variant.capitalize())
axes[0].set_yscale("log")
axes[0].set_ylim(3, 1800)
axes[0].set_yticks([5, 10, 50, 100, 500, 1000])
axes[0].yaxis.set_major_formatter(ScalarFormatter())
axes[0].set_ylabel("Mean query latency (ms, logarithmic scale)")
axes[0].set_title("Graph growth exposed a global property join", fontsize=11, pad=14)
axes[0].legend(frameon=False, loc="upper left")
axes[0].annotate("18.36×", xy=(1, 180), xytext=(1, 330), ha="center", fontsize=11, weight="bold")
axes[0].annotate("122.78×", xy=(2, 834), xytext=(2, 1370), ha="center", fontsize=11, weight="bold")
axes[0].text(0, 4.0, "Intervals overlap", ha="center", fontsize=9)

for variant, offset in (("before", -0.18), ("after", 0.18)):
    values = [case[variant]["allocation_bytes"]["score"] / 1e6 for case in selected]
    bars = axes[1].bar([x + offset for x in range(3)], values, width=0.34,
                       color=colors[variant], label=variant.capitalize())
    axes[1].bar_label(bars, labels=[f"{value:.2f}" for value in values], padding=4, fontsize=9)
axes[1].set_ylim(0, 76)
axes[1].set_ylabel("Allocated MB per query (decimal MB)")
axes[1].set_title("Allocation stays near 3.8 MB in the new path", fontsize=11, pad=14)
axes[1].legend(frameon=False, loc="upper left")

for axis in axes:
    axis.set_xticks(range(3), ["1\n1,088 statements", "64\n69,632 statements", "256\n278,528 statements"])
    axis.set_xlim(-0.5, 2.5)
    axis.set_xlabel("Roots in the stored graph; selected root unchanged", labelpad=10, fontsize=10)
    axis.grid(axis="y", color="#E1E7EB", linewidth=0.7)
    axis.set_axisbelow(True)
figure.text(0.05, 0.035,
            "Two JMH forks; 10 × 2 s warmup and 5 × 2 s measurement per fork. Error bars: reported 99.9% intervals.\n"
            "Shared host; workload-specific results. The one-root allocation increases 10.7%. Full data: summary.json.",
            fontsize=9, linespacing=1.5)
figure.subplots_adjust(left=0.075, right=0.97, bottom=0.23, top=0.79, wspace=0.28)
figure.savefig(directory / "property-scaling.svg", bbox_inches="tight")
svg = directory / "property-scaling.svg"
svg.write_text("\n".join(line.rstrip() for line in svg.read_text().splitlines()).rstrip("\n") + "\n")
figure.savefig(directory / "property-scaling.png", dpi=160, bbox_inches="tight")
plt.close(figure)
